[
  {
    "id": "distinctness-verdict",
    "assert": "the reviewer returned APPROVE",
    "cmd": "test \"$(jq -r .verdict ${design_dir}/verdict-distinctness.json)\" = APPROVE",
    "origin": "pe-profile:design@1.0.0"
  },
  {
    "id": "distinctness-is-substantive",
    "assert": "the review carries at least 200 characters",
    "cmd": "test \"$(jq -r '.findings // \"\" | length' ${design_dir}/verdict-distinctness.json)\" -ge 200",
    "origin": "pe-profile:design@1.0.0"
  },
  {
    "id": "distinctness-engages-with-the-diff",
    "paths": [
      "${design_dir}/doors.json"
    ],
    "context": [
      "${design_dir}/verdict-distinctness.json"
    ],
    "judge": "Does this review judge whether the doors in the diff are genuinely DIFFERENT approaches rather than one approach in three costumes, naming each door and what distinguishes it? FAIL if it approves or rejects without naming specific items from the diff, if it makes a claim the diff does not support, if it is generic enough to apply to any artifact of this kind, or if it leaves part of the diff unjudged.",
    "diff": true,
    "blocking": true,
    "origin": "pe-profile:design@1.0.0"
  }
]

